// Formatear el error para el email
const err = $input.first().json;
const execution = err.execution || {};
const workflow = err.workflow || {};
const lastNode = execution.lastNodeExecuted || 'desconocido';
const errorMsg = (execution.error?.message || err.message || 'Error sin mensaje').toString();
const errorStack = (execution.error?.stack || '').toString().substring(0, 1500);
const executionUrl = execution.url || `${$env.N8N_HOST || ''}/workflow/${workflow.id}/executions/${execution.id}`;
const now = new Date().toLocaleString('es-CR', { timeZone: 'America/Costa_Rica' });

// Datos de entrada que rompió (si los hay)
let inputDataPreview = '';
try {
  const inputData = execution.error?.node?.inputData || {};
  inputDataPreview = JSON.stringify(inputData, null, 2).substring(0, 1000);
} catch (e) {
  inputDataPreview = '(no disponible)';
}

const subject = `🚨 Error n8n: ${workflow.name || 'workflow'} → ${lastNode}`;

const htmlBody = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
  <div style="background: #d32f2f; color: white; padding: 16px; border-radius: 8px 8px 0 0;">
    <h2 style="margin: 0;">🚨 Error en n8n</h2>
  </div>
  <div style="background: #f5f5f5; padding: 20px; border-radius: 0 0 8px 8px;">
    <table style="width: 100%; border-collapse: collapse;">
      <tr><td style="padding: 8px 0; font-weight: bold;">Workflow:</td><td>${workflow.name || 'N/A'}</td></tr>
      <tr><td style="padding: 8px 0; font-weight: bold;">Nodo que falló:</td><td><code>${lastNode}</code></td></tr>
      <tr><td style="padding: 8px 0; font-weight: bold;">Timestamp:</td><td>${now}</td></tr>
      <tr><td style="padding: 8px 0; font-weight: bold;">Execution ID:</td><td>${execution.id || 'N/A'}</td></tr>
    </table>
    <h3 style="color: #d32f2f; margin-top: 20px;">Mensaje de Error</h3>
    <pre style="background: white; padding: 12px; border-radius: 4px; border-left: 4px solid #d32f2f; white-space: pre-wrap; font-size: 12px;">${errorMsg}</pre>
    ${errorStack ? `<h3 style="color: #666; margin-top: 16px;">Stack Trace</h3><pre style="background: white; padding: 12px; border-radius: 4px; font-size: 11px; white-space: pre-wrap;">${errorStack}</pre>` : ''}
    <h3 style="color: #666; margin-top: 16px;">Input Data (preview)</h3>
    <pre style="background: white; padding: 12px; border-radius: 4px; font-size: 11px; white-space: pre-wrap;">${inputDataPreview}</pre>
    <p style="margin-top: 24px;"><a href="${executionUrl}" style="background: #1976d2; color: white; padding: 10px 20px; text-decoration: none; border-radius: 4px;">Ver Ejecución Completa</a></p>
  </div>
  <p style="text-align: center; color: #999; font-size: 11px; margin-top: 16px;">Notificación automática del Error Handler de Bralto</p>
</div>
`;

return [{ json: {
  subject,
  htmlBody,
  workflowName: workflow.name || '',
  workflowId: workflow.id || '',
  executionId: execution.id || '',
  lastNode,
  errorMsg,
  timestamp: now
} }];
